const HEADER: &str =
    "// This file is auto-generated by editor-bindgen. Do not edit.\n\nimport Foundation\n\n";

const SUPPORT: &str = r#"public struct FFIKey: CodingKey, ExpressibleByStringLiteral, Sendable {
  public let stringValue: String
  public var intValue: Int? { nil }

  public init(stringValue: String) {
    self.stringValue = stringValue
  }

  public init?(intValue: Int) {
    nil
  }

  public init(stringLiteral value: String) {
    self.stringValue = value
  }
}

public struct FFIUnit: Codable, Hashable, Sendable {
  public init() {}

  public init(from decoder: any Decoder) throws {
    let container = try decoder.singleValueContainer()
    guard container.decodeNil() else {
      throw DecodingError.dataCorruptedError(in: container, debugDescription: "expected null")
    }
  }

  public func encode(to encoder: any Encoder) throws {
    var container = encoder.singleValueContainer()
    try container.encodeNil()
  }
}
"#;

