    #[test]
    fn variant_wrapping_an_uninhabited_enum_decodes_to_a_throw() {
        let metas = vec![
            enumeration(
                "ParagraphNodeAttr",
                Some("snake_case"),
                Some("type"),
                Some("value"),
                Vec::new(),
            ),
            enumeration(
                "RootNodeAttr",
                Some("snake_case"),
                Some("type"),
                Some("value"),
                vec![unit("Reset")],
            ),
            enumeration(
                "NodeAttr",
                Some("snake_case"),
                Some("type"),
                None,
                vec![
                    FfiVariant::Struct {
                        name: "Root".into(),
                        fields: vec![field("attr", "RootNodeAttr")],
                        serde_rename_all: None,
                    },
                    FfiVariant::Struct {
                        name: "Paragraph".into(),
                        fields: vec![field("attr", "ParagraphNodeAttr")],
                        serde_rename_all: None,
                    },
                ],
            ),
        ];
        let output = render(&metas, "NodeAttr");
        let decode = decode_body(&output);
        assert!(output.contains("  case paragraph(attr: ParagraphNodeAttr)\n"));
        assert!(decode.contains(
            "    case \"paragraph\":\n      throw DecodingError.dataCorruptedError(\n        forKey: \"type\", in: container, debugDescription: \"ParagraphNodeAttr has no variants\")\n"
        ));
        assert!(!decode.contains(".paragraph(attr:"));
        assert!(decode.contains(
            "    case \"root\":\n      self = try .root(attr: container.decode(RootNodeAttr.self, forKey: \"attr\"))"
        ));
        assert!(output.contains(
            "    case .paragraph(let attr):\n      var container = encoder.container(keyedBy: FFIKey.self)\n      try container.encode(\"paragraph\", forKey: \"type\")\n      try container.encode(attr, forKey: \"attr\")"
        ));
    }

    #[test]
    fn adjacent_and_external_variants_wrapping_an_uninhabited_enum_decode_to_a_throw() {
        let variants = || {
            vec![
                FfiVariant::Tuple {
                    name: "Wrapped".into(),
                    tys: vec!["ParagraphNodeAttr".into()],
                },
                FfiVariant::Struct {
                    name: "Nested".into(),
                    fields: vec![field("attr", "ParagraphNodeAttr")],
                    serde_rename_all: None,
                },
                FfiVariant::Struct {
                    name: "Maybe".into(),
                    fields: vec![field("attr", "Option<ParagraphNodeAttr>")],
                    serde_rename_all: None,
                },
            ]
        };
        let metas = vec![
            enumeration(
                "ParagraphNodeAttr",
                Some("snake_case"),
                Some("type"),
                Some("value"),
                Vec::new(),
            ),
            enumeration(
                "Adjacent",
                Some("snake_case"),
                Some("type"),
                Some("value"),
                variants(),
            ),
            enumeration("External", Some("snake_case"), None, None, variants()),
        ];
        for (name, key) in [("Adjacent", "\"type\""), ("External", "key")] {
            let output = render(&metas, name);
            let decode = decode_body(&output);
            for tag in ["wrapped", "nested"] {
                assert!(decode.contains(&format!(
                    "    case \"{tag}\":\n      throw DecodingError.dataCorruptedError(\n        forKey: {key}, in: container, debugDescription: \"ParagraphNodeAttr has no variants\")\n"
                )));
            }
            assert!(!decode.contains(".wrapped("));
            assert!(!decode.contains(".nested("));
            assert!(decode.contains(
                "      self = try .maybe(attr: content.decodeIfPresent(ParagraphNodeAttr.self, forKey: \"attr\"))"
            ));
            assert!(output.contains("  case wrapped(ParagraphNodeAttr)\n"));
            assert!(output.contains("    case .wrapped(let payload):\n"));
            assert!(output.contains("    case .nested(let attr):\n"));
        }
    }

