    #[test]
    fn variant_and_field_keys_follow_their_own_serde_rules() {
        let metas = vec![
            enumeration(
                "PasteKind",
                Some("lowercase"),
                None,
                None,
                vec![unit("HTMLPaste"), unit("PlainText")],
            ),
            enumeration(
                "ClipboardEvent",
                Some("snake_case"),
                Some("type"),
                None,
                vec![
                    unit("HTMLPaste"),
                    FfiVariant::Struct {
                        name: "Commit".into(),
                        fields: vec![field("commit_payload", "String")],
                        serde_rename_all: Some("camelCase".into()),
                    },
                ],
            ),
            structure(
                "Draft",
                Some("camelCase"),
                vec![field("commit_payload", "String")],
            ),
        ];
        let raw = render(&metas, "PasteKind");
        assert!(raw.contains("  case htmlPaste = \"htmlpaste\"\n"), "{raw}");
        assert!(raw.contains("  case plainText = \"plaintext\"\n"), "{raw}");
        let tagged = render(&metas, "ClipboardEvent");
        assert!(
            tagged.contains("    case \"h_t_m_l_paste\":\n      self = .htmlPaste\n"),
            "{tagged}"
        );
        assert!(
            tagged.contains("      try container.encode(\"h_t_m_l_paste\", forKey: \"type\")"),
            "{tagged}"
        );
        assert!(
            tagged.contains(
                "commitPayload: container.decode(String.self, forKey: \"commitPayload\")"
            ),
            "{tagged}"
        );
        let draft = render(&metas, "Draft");
        assert!(
            draft.contains(
                "    commitPayload = try container.decode(String.self, forKey: \"commitPayload\")"
            ),
            "{draft}"
        );
    }

    #[test]
    fn variant_names_follow_serde_variant_rules() {
        for (original, lower, upper, camel, snake, screaming, kebab, screaming_kebab) in [
            (
                "Outcome", "outcome", "OUTCOME", "outcome", "outcome", "OUTCOME", "outcome",
                "OUTCOME",
            ),
            (
                "VeryTasty",
                "verytasty",
                "VERYTASTY",
                "veryTasty",
                "very_tasty",
                "VERY_TASTY",
                "very-tasty",
                "VERY-TASTY",
            ),
            ("A", "a", "A", "a", "a", "A", "a", "A"),
            ("Z42", "z42", "Z42", "z42", "z42", "Z42", "z42", "Z42"),
            (
                "HTMLPaste",
                "htmlpaste",
                "HTMLPASTE",
                "hTMLPaste",
                "h_t_m_l_paste",
                "H_T_M_L_PASTE",
                "h-t-m-l-paste",
                "H-T-M-L-PASTE",
            ),
        ] {
            let rename = |rule| RenameRule::parse(rule, "Sample").apply_to_variant(original);
            assert_eq!(rename(None), original);
            assert_eq!(rename(Some("lowercase")), lower);
            assert_eq!(rename(Some("UPPERCASE")), upper);
            assert_eq!(rename(Some("PascalCase")), original);
            assert_eq!(rename(Some("camelCase")), camel);
            assert_eq!(rename(Some("snake_case")), snake);
            assert_eq!(rename(Some("SCREAMING_SNAKE_CASE")), screaming);
            assert_eq!(rename(Some("kebab-case")), kebab);
            assert_eq!(rename(Some("SCREAMING-KEBAB-CASE")), screaming_kebab);
        }
    }

    #[test]
    fn field_names_follow_serde_field_rules() {
        for (original, upper, pascal, camel, screaming, kebab, screaming_kebab) in [
            (
                "outcome", "OUTCOME", "Outcome", "outcome", "OUTCOME", "outcome", "OUTCOME",
            ),
            (
                "very_tasty",
                "VERY_TASTY",
                "VeryTasty",
                "veryTasty",
                "VERY_TASTY",
                "very-tasty",
                "VERY-TASTY",
            ),
            ("a", "A", "A", "a", "A", "a", "A"),
            ("z42", "Z42", "Z42", "z42", "Z42", "z42", "Z42"),
            (
                "commit_payload",
                "COMMIT_PAYLOAD",
                "CommitPayload",
                "commitPayload",
                "COMMIT_PAYLOAD",
                "commit-payload",
                "COMMIT-PAYLOAD",
            ),
        ] {
            let rename = |rule| RenameRule::parse(rule, "Sample").apply_to_field(original);
            assert_eq!(rename(None), original);
            assert_eq!(rename(Some("lowercase")), original);
            assert_eq!(rename(Some("UPPERCASE")), upper);
            assert_eq!(rename(Some("PascalCase")), pascal);
            assert_eq!(rename(Some("camelCase")), camel);
            assert_eq!(rename(Some("snake_case")), original);
            assert_eq!(rename(Some("SCREAMING_SNAKE_CASE")), screaming);
            assert_eq!(rename(Some("kebab-case")), kebab);
            assert_eq!(rename(Some("SCREAMING-KEBAB-CASE")), screaming_kebab);
        }
    }

